118	+    protected String closingLines(Reservation reservation) {
119	+        return "";
120	+    }
121	+
122	+    public final String text(Reservation reservation, Room room) {
123	+        Words words = words();
124	+        int nights = reservation.price().nights();
125	+        BigDecimal discount = reservation.price().discount();
126	+        StringBuilder text = new StringBuilder();
127	+        text.append(title()).append(' ').append(words.number()).append(' ').append(reservation.id()).append('\n');
128	+        text.append(guestLines(reservation));
129	+        text.append(words.room()).append(": ").append(room.number()).append(" (").append(room.type()).append(")\n");
130	+        text.append(words.checkIn()).append(": ").append(date(reservation.checkIn()))
131	+                .append(" | ").append(words.checkOut()).append(": ").append(date(reservation.checkOut()))
132	+                .append(" | ").append(nights).append(' ').append(nights == 1 ? words.night() : words.nights())
133	+                .append('\n');
134	+        text.append(words.subtotal()).append(": ").append(money(reservation.price().subtotal())).append('\n');
