 10	/**
 11	 * The document the guest gets when the reservation is confirmed, at check-out, and on request: a
 12	 * receipt, an invoice or a booking receipt, according to how the guest is identified.
 13	 */
 14	public record ReservationReceipt(
 15	        String title,
 16	        long reservationId,
 17	        String guestName,
 18	        String guestCpf,
 19	        String companyCnpj,
 20	        String companyName,
 21	        String guestPassport,
 22	        String guestCountry,
 23	        int roomNumber,
 24	        RoomType roomType,
 25	        LocalDate checkIn,
 26	        LocalDate checkOut,
 27	        int nights,
 28	        BigDecimal subtotal,
 29	        BigDecimal discount,
 30	        BigDecimal total,
 31	        String text) {
 32	
 33	    public ReservationReceipt(Reservation reservation, Room room) {
 34	        this(reservation, room, reservation.guest().identification());
 35	    }
 36	
 37	    private ReservationReceipt(Reservation reservation, Room room, Identification identification) {
 38	        this(
 39	                identification.documentLayout().title(),
 40	                reservation.id(),
 41	                reservation.guest().name(),
 42	                identification.cpf(),
 43	                identification.companyCnpj(),
 44	                identification.companyName(),
 45	                identification.passport(),
 46	                identification.country(),
 47	                room.number(),
 48	                room.type(),
 49	                reservation.checkIn(),
 50	                reservation.checkOut(),
 51	                reservation.price().nights(),
 52	                reservation.price().subtotal(),
 53	                reservation.price().discount(),
 54	                reservation.price().total(),
 55	                identification.documentLayout().text(reservation, room));
 56	    }
 57	}
