 10	import hotel.reservations.ErrorCode;
 11	import hotel.reservations.Guest;
 12	import hotel.reservations.HotelException;
 13	import hotel.reservations.Identification;
 14	import hotel.reservations.NewReservation;
 15	import hotel.reservations.ReservationService;
 16	import hotel.rooms.Rooms;
 17	import io.javalin.Javalin;
 18	import io.javalin.http.Context;
 19	import io.javalin.json.JavalinJackson;
 20	import java.time.LocalDate;
 21	import java.time.YearMonth;
 22	import java.time.format.DateTimeParseException;
 23	
 24	/** The HTTP API the inn's website and front desk call. */
 25	public final class HttpApi {
 26	
 27	    private final Javalin server;
 28	    private final Rooms rooms;
 29	    private final ReservationService reservations;
 30	    private final SentMessages sentMessages;
 31	    private final OccupancyReport occupancyReport;
 32	    private final RevenueReport revenueReport;
 33	
 34	    public HttpApi(
 35	            Rooms rooms,
 36	            ReservationService reservations,
 37	            SentMessages sentMessages,
 38	            OccupancyReport occupancyReport,
 39	            RevenueReport revenueReport) {
 40	        this.rooms = rooms;
 41	        this.reservations = reservations;
 42	        this.sentMessages = sentMessages;
 43	        this.occupancyReport = occupancyReport;
 44	        this.revenueReport = revenueReport;
 45	
 46	        ObjectMapper jsonMapper = JsonMapper.builder()
 47	                .addModule(new JavaTimeModule())
 48	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 49	                .build();
 50	        this.server = Javalin.create(config -> {
 51	            config.showJavalinBanner = false;
 52	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 53	        });
 54	        registerRoutes();
 55	        registerErrorHandling();
 56	    }
 57	
 58	    public Javalin server() {
 59	        return server;
 60	    }
 61	
 62	    private void registerRoutes() {
 63	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 64	
 65	        server.post("/reservations", ctx -> {
 66	            NewReservation request = readNewReservation(ctx);
 67	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
 68	        });
 69	        server.get("/reservations/{id}", ctx ->
 70	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
 71	        server.post("/reservations/{id}/confirmation", ctx ->
 72	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
 73	        server.post("/reservations/{id}/cancellation", ctx ->
 74	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
 75	        server.post("/reservations/{id}/check-in", ctx ->
 76	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
 77	        server.post("/reservations/{id}/check-out", ctx ->
 78	                ctx.json(reservations.checkOut(reservationId(ctx))));
 79	        server.get("/reservations/{id}/document", ctx ->
 80	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 81	
 82	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 83	
 84	        server.get("/reports/occupancy", ctx -> {
 85	            LocalDate night = readDate(ctx);
 86	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
 87	        });
 88	        server.get("/reports/revenue", ctx -> {
 89	            YearMonth month = readMonth(ctx);
 90	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
 91	        });
 92	    }
 93	
 94	    private void registerErrorHandling() {
 95	        server.exception(HotelException.class, (exception, ctx) -> {
 96	            ctx.status(httpStatus(exception.errorCode()));
 97	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 98	        });
 99	    }
100	
101	    private static int httpStatus(ErrorCode errorCode) {
102	        return switch (errorCode) {
103	            case INVALID_REQUEST -> 400;
104	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
105	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
106	            case CAPACITY_EXCEEDED -> 422;
107	        };
108	    }
109	
110	    private static NewReservation readNewReservation(Context ctx) {
111	        CreateReservationRequest body;
112	        try {
113	            body = ctx.bodyAsClass(CreateReservationRequest.class);
114	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
115	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
116	        }
117	        if (body == null
118	                || body.roomNumber() == null
119	                || isBlank(body.guestName())
120	                || isBlank(body.guestEmail())
121	                || body.checkIn() == null
122	                || body.checkOut() == null
123	                || body.guests() == null
124	                || body.ratePlan() == null) {
125	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
126	        }
127	        Guest guest = new Guest(body.guestName(), body.guestEmail(), readIdentification(body));
128	        return new NewReservation(
129	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
130	    }
131	
132	    /** The guest is identified in exactly one way: CPF, or CNPJ with company name, or passport with country. */
133	    private static Identification readIdentification(CreateReservationRequest body) {
134	        boolean anyCpf = !isBlank(body.guestCpf());
135	        boolean anyCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
136	        boolean anyPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
137	        boolean company = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
138	        boolean passport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
139	        int ways = (anyCpf ? 1 : 0) + (anyCompany ? 1 : 0) + (anyPassport ? 1 : 0);
140	        if (ways != 1 || (anyCompany && !company) || (anyPassport && !passport)) {
141	            throw new HotelException(ErrorCode.INVALID_REQUEST,
142	                    "identify the guest by the CPF, or by the CNPJ with the company name, "
143	                            + "or by the passport with the country");
144	        }
145	        if (company) {
146	            return new Identification.Company(body.companyCnpj(), body.companyName());
147	        }
148	        if (passport) {
149	            return new Identification.Passport(body.guestPassport(), body.guestCountry());
150	        }
151	        return new Identification.Cpf(body.guestCpf());
152	    }
