155	        String id = ctx.pathParam("id");
156	        try {
157	            return Long.parseLong(id);
158	        } catch (NumberFormatException notANumber) {
159	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
160	        }
161	    }
