164	        String date = requiredQueryParam(ctx, "date");
165	        try {
166	            return LocalDate.parse(date);
167	        } catch (DateTimeParseException badDate) {
168	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
169	        }
170	    }
